class ArrowSpinBox(QSpinBox):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setButtonSymbols(QAbstractSpinBox.NoButtons)
        self.setStyleSheet(self.styleSheet() + " QSpinBox { padding-right: 22px; }")

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setPen(self.palette().color(self.foregroundRole()))
        font = painter.font()
        font.setPointSize(7)
        painter.setFont(font)

        arrow_width = 14
        arrow_x = self.width() - arrow_width - 3
        half_height = self.height() // 2

        painter.drawText(
            arrow_x, 0, arrow_width, half_height,
            Qt.AlignCenter, "▲"
        )
        painter.drawText(
            arrow_x, half_height, arrow_width, self.height() - half_height,
            Qt.AlignCenter, "▼"
        )
        painter.end()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and event.position().x() >= self.width() - 30:
            if event.position().y() < self.height() / 2:
                self.stepUp()
            else:
                self.stepDown()
            event.accept()
            return
        super().mousePressEvent(event)


