class ArrowTree(QTreeWidget):
    """Tree that draws its own expand/collapse arrows so the arrow
    turns white on the selected (blue) row."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.arrow_idle = QColor("#FFFFFF")

    def drawBranches(self, painter, rect, index):
        if not self.model().hasChildren(index):
            return

        selected = self.selectionModel().isSelected(index)
        color = QColor("#FFFFFF") if selected else self.arrow_idle

        size = self.indentation()
        cell_x = rect.right() - size + 1
        cx = cell_x + size // 2
        cy = rect.top() + rect.height() // 2

        painter.save()
        painter.setRenderHint(QPainter.Antialiasing)
        pen = painter.pen()
        pen.setColor(color)
        pen.setWidthF(1.8)
        pen.setCapStyle(Qt.RoundCap)
        pen.setJoinStyle(Qt.RoundJoin)
        painter.setPen(pen)

        if self.isExpanded(index):
            points = [QPoint(cx - 4, cy - 2), QPoint(cx, cy + 2), QPoint(cx + 4, cy - 2)]
        else:
            points = [QPoint(cx - 2, cy - 4), QPoint(cx + 2, cy), QPoint(cx - 2, cy + 4)]
        painter.drawPolyline(points)
        painter.restore()

class NewValueTableDialog(QDialog):
    """Create or edit a signal value table (raw integer → readable string)."""

    def __init__(self, parent=None, name="", choices=None):
        super().__init__(parent)
        self.setWindowTitle("Value Table" if choices else "New Value Table")
        self.resize(420, 320)

        root = QVBoxLayout(self)
        root.setContentsMargins(14, 12, 14, 12)
        root.setSpacing(8)

        name_row = QHBoxLayout()
        name_row.addWidget(QLabel("Name:"))
        self.name_edit = QLineEdit(name or "")
        self.name_edit.setPlaceholderText("Optional label (e.g. EngineState)")
        name_row.addWidget(self.name_edit, 1)
        root.addLayout(name_row)

        hint = QLabel("Value must be a number (0, 1, 2, 255, 0xFF...). Description can be any text.")
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #888; font-size: 11px;")
        root.addWidget(hint)

        self.table = QTableWidget(0, 2)
        self.table.setHorizontalHeaderLabels(["Value", "Description"])
        self.table.horizontalHeader().setStretchLastSection(True)
        self.table.setSelectionBehavior(QTableWidget.SelectRows)
        root.addWidget(self.table, 1)

        table_buttons = QHBoxLayout()
        add_button = QPushButton("Add")
        delete_button = QPushButton("Delete")
        add_button.clicked.connect(self.add_row)
        delete_button.clicked.connect(self.delete_row)
        table_buttons.addWidget(add_button)
        table_buttons.addWidget(delete_button)
        table_buttons.addStretch()
        root.addLayout(table_buttons)

        buttons = QHBoxLayout()
        buttons.addStretch()
        ok_button = QPushButton("OK")
        cancel_button = QPushButton("Cancel")
        ok_button.clicked.connect(self.accept)
        cancel_button.clicked.connect(self.reject)
        buttons.addWidget(ok_button)
        buttons.addWidget(cancel_button)
        root.addLayout(buttons)

        if choices:
            for value, description in sorted(choices.items(), key=lambda x: x[0]):
                row = self.table.rowCount()
                self.table.insertRow(row)
                self.table.setItem(row, 0, QTableWidgetItem(str(value)))
                self.table.setItem(row, 1, QTableWidgetItem(str(description)))
        else:
            self.add_row()

    def add_row(self):
        row = self.table.rowCount()
        self.table.insertRow(row)
        self.table.setItem(row, 0, QTableWidgetItem(""))
        self.table.setItem(row, 1, QTableWidgetItem(""))
        self.table.setCurrentCell(row, 0)

    def delete_row(self):
        row = self.table.currentRow()
        if row >= 0:
            self.table.removeRow(row)

    def get_data(self):
        choices = {}
        invalid_rows = []

        for row in range(self.table.rowCount()):
            value_item = self.table.item(row, 0)
            description_item = self.table.item(row, 1)

            value_text = value_item.text().strip() if value_item else ""
            description = description_item.text().strip() if description_item else ""

            if not value_text and not description:
                continue  # completely empty row → ignore

            if not value_text:
                invalid_rows.append(row + 1)
                continue

            try:
                value = int(value_text, 0)  # supports 0xFF, 0b1010, etc.
            except ValueError:
                invalid_rows.append(row + 1)
                continue

            choices[value] = description

        if invalid_rows:
            QMessageBox.warning(
                self,
                "Invalid Value",
                f"Value column must contain only numbers.\n"
                f"Problem in row(s): {', '.join(map(str, invalid_rows))}\n\n"
                f"Example of correct entries:\n"
                f"0 → Off\n1 → On\n2 → Error"
            )
            return None, None   # signal that data is invalid

        name = self.name_edit.text().strip()
        if not name and choices:
            name = "Custom"
        return name, choices
  
