    def keyPressEvent(self, event):
        if event.key() in (Qt.Key_Return, Qt.Key_Enter):
            self.accept_changes()
            event.accept()
            return
        super().keyPressEvent(event)

    def create_double_field(self, layout, label):
        container = QVBoxLayout()
        container.addWidget(QLabel(label))
        box = ArrowDoubleSpinBox()
        box.setRange(-1000000000, 1000000000)
        box.setDecimals(3)
        box.setSingleStep(0.1)
        box.setButtonSymbols(QAbstractSpinBox.UpDownArrows)
        box.setAccelerated(True)
        box.setKeyboardTracking(True)
        box.setValue(0.0)
        container.addWidget(box)
        layout.addLayout(container)
        return box

    def create_int_field(self, layout, label, minimum, maximum,fixed_width=None):
        container = QVBoxLayout()
        container.addWidget(QLabel(label))
        box = ArrowSpinBox()
        box.setRange(minimum, maximum)
        box.setSingleStep(1)
        box.setButtonSymbols(QAbstractSpinBox.UpDownArrows)
