    # =========================================================
    # OPEN DBC FILES
    # =========================================================

    def open_dbc_files(self):

        paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Open DBC Files",
            "",
            "DBC Files (*.dbc)"
        )

        if paths:

            self.load_multiple_dbc_files(
                paths
            )

    # =========================================================
    # LOAD MULTIPLE FILES
    # =========================================================

    def load_multiple_dbc_files(
        self,
        paths
    ):

        successful = []

        failed = []

        for path in paths:

            try:

                database = (
                    cantools.database.load_file(
                        path
                    )
                )

                self.databases[path] = (
                    database
                )
                self.pending_save_as.add(os.path.abspath(path))
                successful.append(
                    path
                )

            except Exception as error:

                failed.append(
                    f"{os.path.basename(path)}\n"
                    f"{error}"
                )

        if successful:


            self.current_file = (
                successful[-1]
            )

            self.update_file_list()

            self.update_database_tree()

            self.update_statistics()

            self.show_overview()
            self.save_session() 

        if failed:

            QMessageBox.warning(
                self,
                "Some Files Could Not Be Loaded",
                "\n\n".join(
                    failed
                )
            )

    # =========================================================
    # UPDATE FILE LIST
    # =========================================================

    def update_file_list(self):

        self.file_list.clear()

        for path in self.databases:

            item = QListWidgetItem()
            item.setData(Qt.UserRole, path)

            row = QWidget()
            row.setObjectName("fileRow")
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(6, 2, 5, 2)
            row_layout.setSpacing(3)

            name_button = FileNameButton(
                f"●  {os.path.basename(path)}"
            )
            name_button.setObjectName("fileNameButton")
            name_button.setFlat(True)
            name_button.setToolTip(os.path.basename(path))
            name_button.clicked.connect(
                lambda checked=False, p=path: self.file_selected_by_path(p)
            )
            name_button.doubleClicked.connect(
                lambda p=path: self.file_item_double_clicked_path(p)
            )

            save_button = QToolButton()
            save_button.setIcon(self.create_traditional_icon("save", "#000000" if self.current_theme == "light" else "#FFFFFF"))
            save_button.setIconSize(QSize(14, 14))
            save_button.setObjectName("fileActionButton")
            save_button.setToolTip("Save DBC file")
            save_button.setAutoRaise(True)
            save_button.clicked.connect(
                lambda checked=False, p=path: self.save_dbc_file(p)
            )

            delete_button = QToolButton()
            delete_button.setIcon(self.create_traditional_icon("delete", "#000000" if self.current_theme == "light" else "#FFFFFF"))
            delete_button.setIconSize(QSize(14, 14))
            delete_button.setObjectName("fileDeleteButton")
            delete_button.setToolTip("Remove DBC file from DBC Studio")
            delete_button.setAutoRaise(True)
            delete_button.clicked.connect(
                lambda checked=False, p=path: self.delete_file_by_path(p)
            )

            row_layout.addWidget(name_button, 1)
            row_layout.addWidget(save_button)
            row_layout.addWidget(delete_button)

            self.file_list.addItem(item)
            self.file_list.setItemWidget(item, row)
            item.setSizeHint(row.sizeHint())

            if path == self.current_file:
                self.file_list.setCurrentItem(item)
                self.set_file_row_selected(item, True)
            else:
                self.set_file_row_selected(item, False)

    def create_traditional_icon(self, icon_type, color):
        if icon_type == "save":
            return create_tinted_embedded_icon(
                SAVE_FILE_ICON_DATA,
                color
            )

        if icon_type == "delete":
            return create_tinted_embedded_icon(
                DELETE_FILE_ICON_DATA,
                color
            )

        return QIcon()

    def set_file_row_selected(self, item, selected):
        row = self.file_list.itemWidget(item)
        if row is None:
            return
        row.setProperty("selected", bool(selected))
        row.style().unpolish(row)
        row.style().polish(row)
        for child in row.findChildren(QPushButton):
            child.setProperty("selected", bool(selected))
            child.style().unpolish(child)
            child.style().polish(child)
        for child in row.findChildren(QToolButton):
            child.setVisible(bool(selected) and self.file_action_visible_path == item.data(Qt.UserRole))
            child.setProperty("selected", bool(selected))
            child.style().unpolish(child)
            child.style().polish(child)
            # Light theme: white icons when selected, black when not
            if self.current_theme == "light":
                icon_color = "#FFFFFF" if selected else "#000000"
            else:
                icon_color = "#FFFFFF"
            if child.objectName() == "fileActionButton":
                child.setIcon(self.create_traditional_icon("save", icon_color))
            elif child.objectName() == "fileDeleteButton":
                child.setIcon(self.create_traditional_icon("delete", icon_color))

    def file_selected_by_path(self, path):
        if path not in self.databases:
            return
        self.current_file = path
        self.file_action_visible_path = path
        self.sidebar_tree.clearSelection()
        for index in range(self.file_list.count()):
            item = self.file_list.item(index)
            selected = item.data(Qt.UserRole) == path
            item.setSelected(selected)
            self.set_file_row_selected(item, selected)
        self.search_box.clear()
        self.update_statistics()
        self.update_database_tree()
        self.show_overview()

        

    def file_item_double_clicked(self, item, column):
        path = item.data(Qt.UserRole)
        self.file_item_double_clicked_path(path)

    def file_item_double_clicked_path(self, path):
        if path not in self.databases:
            return
        self.current_file = path
        self.sidebar_tree.clearSelection()
        self.file_action_visible_path = path
        for index in range(self.file_list.count()):
            list_item = self.file_list.item(index)
            selected = list_item.data(Qt.UserRole) == path
            list_item.setSelected(selected)
            self.set_file_row_selected(list_item, selected)
        self.search_box.clear()
        self.update_statistics()
        self.update_database_tree()
        self.show_overview()

    # =========================================================
    # UPDATE DATABASE TREE
    # =========================================================

    def update_database_tree(self, force_expand_key=None):
        if (
            hasattr(self, "search_box")
            and self.search_box.text().strip()
           ):
             self.search_database(
                self.search_box.text()
            )
             return
        expanded_keys = set()

        def expansion_key(item):
            data = item.data(0, Qt.UserRole)
            if not data:
                return None

            if data[0] == "file_root":
                return ("file_root", data[1])

            if data[0] == "node":
                return ("node", data[1].name)

            if data[0] == "message":
                return (
                    "message",
                    data[1].frame_id,
                    data[1].name
                )

            if data[0] == "signal":
                return (
                    "signal",
                    data[1].frame_id,
                    data[2].name
                )

            return None

        def save_expansion(item):
            key = expansion_key(item)
            if key is not None and item.isExpanded():
                expanded_keys.add(key)

            for child_index in range(item.childCount()):
                save_expansion(item.child(child_index))

        for top_index in range(self.sidebar_tree.topLevelItemCount()):
            save_expansion(self.sidebar_tree.topLevelItem(top_index))

        if force_expand_key is not None:
            expanded_keys.add(force_expand_key)

        self.update_search_completer()

        self.sidebar_tree.clear()

        database = (
            self.get_current_database()
        )

        if database is None:

            return

        # -----------------------------------------------------
        # FILE ROOT
        # -----------------------------------------------------

        file_root = QTreeWidgetItem(
            self.sidebar_tree
        )

        file_root.setText(
            0,
            os.path.basename(self.current_file)
        )
        file_root.setIcon(0, self.file_tree_icon)

        file_root.setData(
            0,
            Qt.UserRole,
            (
                "file_root",
                self.current_file
            )
        )

        # The DBC file itself stays open after parsing/loading.
        file_root.setExpanded(
            True
        )

        # -----------------------------------------------------
        # NODES
        #
        # Nodes are placed directly under the DBC file. There is
        # intentionally no separate "NODES" tree level.
        # -----------------------------------------------------

        node_items = {}

        for node in database.nodes:

            node_item = QTreeWidgetItem(
                file_root
            )

            node_item.setText(
                0,
                node.name
            )
            node_item.setIcon(0, self.node_tree_icon)

            node_item.setData(
                0,
                Qt.UserRole,
                (
                    "node",
                    node
                )
            )

            # Nodes open only when the user opens/clicks the node.
            node_item.setExpanded(
                False
            )

            node_items[
                node.name
            ] = node_item

        # -----------------------------------------------------
        # MESSAGES
        # -----------------------------------------------------

        unassigned = None

        for message in database.messages:

            added = False

            for sender in message.senders:

                if sender in node_items:

                    self.add_message_tree(
                        node_items[sender],
                        message
                    )

                    added = True

            if added:

                continue

            # -------------------------------------------------
            # UNASSIGNED
            #
            # Keep unassigned messages directly under the DBC file
            # as well, rather than creating another NODES level.
            # -------------------------------------------------

            if unassigned is None:

                unassigned = QTreeWidgetItem(
                    file_root
                )

                unassigned.setText(
                    0,
                    "UNASSIGNED MESSAGES"
                )
                unassigned.setIcon(0, self.message_tree_icon)

                unassigned.setExpanded(
                    False
                )

            self.add_message_tree(
                unassigned,
                message
            )

        # Restore every branch that was already open before the
        # tree was rebuilt. Newly created branches remain closed.
        def restore_expansion(item):
            key = expansion_key(item)
            if key in expanded_keys:
                item.setExpanded(True)

            for child_index in range(item.childCount()):
                restore_expansion(item.child(child_index))

        for top_index in range(self.sidebar_tree.topLevelItemCount()):
            restore_expansion(self.sidebar_tree.topLevelItem(top_index))

        # The DBC root must remain open so its first level is visible.
        file_root.setExpanded(True)
        self.refresh_tree_item_icons()

    # =========================================================
    # ADD MESSAGE TO NODE
    # =========================================================

    def add_message_tree(
        self,
        parent,
        message
    ):

        message_item = QTreeWidgetItem(
            parent
        )
        

        message_item.setText(
        0,
        f"{message.name} [0x{message.frame_id:03X}]"
    )
        message_item.setIcon(0, self.message_tree_icon)

        message_item.setData(
            0,
            Qt.UserRole,
            (
                "message",
                message
            )
        )

        # -----------------------------------------------------
        # SIGNALS
        # -----------------------------------------------------

        for signal in message.signals:

            signal_item = QTreeWidgetItem(
                message_item
            )

            signal_item.setText(
                0,
                signal.name
            )
            signal_item.setIcon(0, self.signal_tree_icon)

            signal_item.setData(
                0,
                Qt.UserRole,
                (
                    "signal",
                    message,
                    signal
                )
            )

    # =========================================================
    # FILE SELECTED
    # =========================================================

    def file_selected(
        self,
        item
    ):

        path = item.data(Qt.UserRole)
        self.file_selected_by_path(path)

    # =========================================================
    # SAVE DBC FILE
    # =========================================================


    def save_dbc_file(self, path=None):

       if path is None:
           path = self.current_file

       if not path or path not in self.databases:
         QMessageBox.information(
            self,
            "No File Selected",
            "Please select a DBC file first."
         )
         return False
       previous = self.current_file
       self.current_file = path
       try:
           return self.save_current_file()
       finally:
        # Restore only if save_current_file did not change current_file
          if self.current_file == path:
            self.current_file = previous
       
    def save_current_file(self):

      if not self.current_file or self.current_file not in self.databases:
        QMessageBox.information(
            self,
            "No File Selected",
            "Please select a DBC file first."
        )
        return False

      database = self.databases[self.current_file]
      current_path = os.path.abspath(self.current_file)
      needs_save_as = (
          current_path in self.pending_save_as
          or not os.path.isfile(current_path)
        )
      
      if not needs_save_as:
        save_path = current_path
      else:
        default_name = current_path
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save DBC File",
            default_name,
            "DBC Files (*.dbc)"
         )

        if not save_path:
            return False

        if not save_path.lower().endswith(".dbc"):
            save_path += ".dbc"

        save_path = os.path.abspath(save_path)

        if os.path.isfile(save_path) and save_path != current_path:
            answer = QMessageBox.question(
                self,
                "File Already Exists",
                f"The file already exists:\n\n"
                f"{save_path}\n\n"
                "Do you want to replace it?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )

            if answer != QMessageBox.Yes:
                return False

      try:

          # Do not refresh here.
          # cantools refresh() rebuilds the name dictionary and reports
          # duplicate message names such as "wer".

          cantools.database.dump_file(
            database,
            save_path,
            database_format="dbc",
            sort_signals=None
          )

          if not os.path.isfile(save_path):
            raise IOError(
                f"The DBC file was not created at:\n{save_path}"
            )
          self.pending_save_as.discard(current_path)
          self.pending_save_as.discard(save_path)

          if save_path != current_path:

            self.databases[save_path] = database

            if current_path in self.databases:
                del self.databases[current_path]

            self.current_file = save_path
            self.file_action_visible_path = save_path

            self.update_file_list()
            self.update_database_tree()
            self.update_statistics()
            self.show_overview()
            self.save_session()

          return True

      except Exception as error:

           QMessageBox.critical(
            self,
            "Save Error",
            f"Could not save the DBC file.\n\n{error}"
           )
           
           return False

    # =========================================================
    # DELETE FILE
    # =========================================================

    def delete_selected_file(self):
        self.delete_file_by_path(self.current_file)

    def delete_file_by_path(self, path):

        if not path or path not in self.databases:
            QMessageBox.information(
                self,
                "No File Selected",
                "Please select a DBC file first."
            )
            return

        filename = os.path.basename(path)

        answer = QMessageBox.question(
            self,
            "Remove DBC File",
            f"Are you sure you want to remove\n"
            f"'{filename}' from DBC Studio?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )

        if answer != QMessageBox.Yes:
            return

        was_current = path == self.current_file
        del self.databases[path]
        self.pending_save_as.discard(path)

        if not self.databases:
            self.current_file = None
            self.file_list.clear()
            self.sidebar_tree.clear()
            self.update_statistics()
            self.show_welcome()
            self.save_session()
            return

        if was_current:
            self.current_file = next(iter(self.databases))

        self.update_file_list()
        self.update_database_tree()
        self.update_statistics()
        self.show_overview()

        self.save_session()   # also add this line inside delete_file_by_path (see Step 4)

    def save_session(self):
        """Remember which DBC files were open so they come back next launch."""
        paths = list(self.databases.keys())
        self.settings.setValue("open_files", paths)
        self.settings.setValue("current_file", self.current_file or "")
        self.settings.sync()

    def restore_session(self):
        """Reload previously open DBC files from disk."""
        paths = self.settings.value("open_files", [])
        if paths is None:
            paths = []
        elif isinstance(paths, str):
            paths = [paths] if paths else []

        existing = [p for p in paths if isinstance(p, str) and os.path.isfile(p)]
        if not existing:
            return False

        successful = []
        for path in existing:
            try:
                database = cantools.database.load_file(path)
                self.databases[path] = database
                successful.append(path)
            except Exception:
                pass

        if not successful:
            return False

        saved_current = self.settings.value("current_file", "")
        if saved_current in self.databases:
            self.current_file = saved_current
        else:
            self.current_file = successful[-1]

        self.update_file_list()
        self.update_database_tree()
        self.update_statistics()
        self.show_overview()
        return True

    def closeEvent(self, event):
        self.save_session()
        super().closeEvent(event)

   


    # =========================================================
    # EXPORT SELECTED FILE
    # =========================================================

    def export_selected_file(self):

        if not self.current_file or self.current_file not in self.databases:
            QMessageBox.information(
                self,
                "No File Selected",
                "Please select a DBC file first."
            )
            return

        dialog = QDialog(self)
        dialog.setWindowTitle("Export DBC File")
        dialog.setModal(True)
        dialog.resize(390, 180)

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(20, 18, 20, 18)
        layout.setSpacing(12)

        label = QLabel("Choose export format:")
        layout.addWidget(label)

        combo = QComboBox()
        combo.addItems(["DBC", "XML", "CSV"])
        layout.addWidget(combo)

        buttons = QHBoxLayout()
        buttons.addStretch()
        cancel = QPushButton("Cancel")
        export = QPushButton("Export")
        buttons.addWidget(cancel)
        buttons.addWidget(export)
        layout.addLayout(buttons)

        cancel.clicked.connect(dialog.reject)
        export.clicked.connect(dialog.accept)

        if dialog.exec() != QDialog.Accepted:
            return

        fmt = combo.currentText()
        database = self.databases[self.current_file]
        base_name = os.path.splitext(os.path.basename(self.current_file))[0]

        if fmt == "DBC":
            selected_filter = "DBC Files (*.dbc)"
            default_name = base_name + ".dbc"
        elif fmt == "XML":
            selected_filter = "XML Files (*.xml)"
            default_name = base_name + ".xml"
        else:
            selected_filter = "CSV Files (*.csv)"
            default_name = base_name + ".csv"

        output_path, _ = QFileDialog.getSaveFileName(
            self,
            f"Export {fmt}",
            default_name,
            selected_filter
        )

        if not output_path:
            return

        try:
            if fmt == "DBC":
                cantools.database.dump_file(
                    database,
                    output_path,
                    database_format="dbc",
                    sort_signals=None
                )
            elif fmt == "XML":
                self.export_database_xml(database, output_path)
            else:
                self.export_database_csv(database, output_path)

            QMessageBox.information(
                self,
                "Export Successful",
                f"{fmt} file exported successfully.\n\n{output_path}"
            )

        except Exception as error:
            QMessageBox.critical(
                self,
                "Export Error",
                f"Could not export the {fmt} file.\n\n{error}"
            )

    def export_database_xml(self, database, output_path):

        root = ET.Element("DBC")
        ET.SubElement(root, "FileName").text = os.path.basename(self.current_file or "")

        nodes_element = ET.SubElement(root, "Nodes")
        for node in database.nodes:
            ET.SubElement(nodes_element, "Node", {"name": str(node.name)})

        messages_element = ET.SubElement(root, "Messages")
        for message in database.messages:
            message_element = ET.SubElement(
                messages_element,
                "Message",
                {
                    "name": str(message.name),
                    "frame_id": str(message.frame_id),
                    "identifier": f"0x{message.frame_id:X}",
                    "length": str(message.length),
                    "is_extended": str(bool(message.is_extended_frame)).lower(),
                    "senders": ", ".join(message.senders or [])
                }
            )

            if getattr(message, "comment", None):
                ET.SubElement(message_element, "Description").text = str(message.comment)

            signals_element = ET.SubElement(message_element, "Signals")
            for signal in message.signals:
                signal_element = ET.SubElement(
                    signals_element,
                    "Signal",
                    {
                        "name": str(signal.name),
                        "start": str(signal.start),
                        "length": str(signal.length),
                        "byte_order": str(signal.byte_order),
                        "is_signed": str(bool(signal.is_signed)).lower(),
                        "scale": str(signal.scale),
                        "offset": str(signal.offset),
                        "unit": str(signal.unit or "")
                    }
                )
                if signal.minimum is not None:
                    signal_element.set("minimum", str(signal.minimum))
                if signal.maximum is not None:
                    signal_element.set("maximum", str(signal.maximum))
                if getattr(signal, "comment", None):
                    ET.SubElement(signal_element, "Description").text = str(signal.comment)

        tree = ET.ElementTree(root)
        try:
            ET.indent(tree, space="  ")
        except AttributeError:
            pass
        tree.write(output_path, encoding="utf-8", xml_declaration=True)

    def export_database_csv(self, database, output_path):

        with open(output_path, "w", newline="", encoding="utf-8-sig") as csv_file:
            writer = csv.writer(csv_file)
            writer.writerow([
                "Node",
                "Message",
                "Frame ID",
                "CAN Type",
                "Message Length",
                "Signal",
                "Start Bit",
                "Signal Length",
                "Byte Order",
                "Signed",
                "Scale",
                "Offset",
                "Minimum",
                "Maximum",
                "Unit",
                "Description"
            ])

            for message in database.messages:
                senders = message.senders or [""]
                signals = message.signals or [None]

                for sender in senders:
                    for signal in signals:
                        writer.writerow([
                            sender,
                            message.name,
                            f"0x{message.frame_id:X}",
                            "XTD" if message.is_extended_frame else "STD",
                            message.length,
                            signal.name if signal else "",
                            signal.start if signal else "",
                            signal.length if signal else "",
                            signal.byte_order if signal else "",
                            signal.is_signed if signal else "",
                            signal.scale if signal else "",
                            signal.offset if signal else "",
                            signal.minimum if signal and signal.minimum is not None else "",
                            signal.maximum if signal and signal.maximum is not None else "",
                            signal.unit if signal else "",
                            (
                                getattr(signal, "comment", "") or ""
                                if signal
                                else getattr(message, "comment", "") or ""
                            )
                        ])

    def export_database_pdf(self, database, output_path):

        writer = QPdfWriter(output_path)
        writer.setPageSize(QPageSize(QPageSize.A4))
        writer.setTitle(f"DBC Studio - {os.path.basename(self.current_file or '')}")

        painter = QPainter(writer)
        if not painter.isActive():
            raise RuntimeError("Could not create PDF output file.")

        try:
            page_width = writer.width()
            page_height = writer.height()
            margin = 70
            y = margin
            line_height = 28

            title_font = QFont("Arial", 16)
            title_font.setBold(True)
            painter.setFont(title_font)
            painter.drawText(
                margin, y,
                f"DBC Studio - {os.path.basename(self.current_file or '')}"
            )
            y += 45

            body_font = QFont("Arial", 9)
            painter.setFont(body_font)

            def line(text, indent=0):
                nonlocal y
                if y > page_height - margin:
                    writer.newPage()
                    y = margin
                    painter.setFont(body_font)
                painter.drawText(margin + indent, y, str(text))
                y += line_height

            line(f"Nodes: {len(database.nodes)}")
            line(f"Messages: {len(database.messages)}")
            line(
                "Signals: " +
                str(sum(len(message.signals) for message in database.messages))
            )
            y += 10

            for node in database.nodes:
                line(f"Node: {node.name}")

                node_messages = [
                    message for message in database.messages
                    if node.name in (message.senders or [])
                ]

                for message in node_messages:
                    line(
                        f"Message: {message.name} | ID: 0x{message.frame_id:X} | "
                        f"DLC: {message.length}",
                        20
                    )
                    for signal in message.signals:
                        line(
                            f"Signal: {signal.name} | Start: {signal.start} | "
                            f"Length: {signal.length} | {signal.byte_order} | "
                            f"Signed: {signal.is_signed}",
                            40
                        )

            unassigned = [
                message for message in database.messages
                if not message.senders or not any(
                    node.name in message.senders for node in database.nodes
                )
            ]

            if unassigned:
                line("Unassigned Messages:")
                for message in unassigned:
                    line(
                        f"Message: {message.name} | ID: 0x{message.frame_id:X} | "
                        f"DLC: {message.length}",
                        20
                    )
                    for signal in message.signals:
                        line(
                            f"Signal: {signal.name} | Start: {signal.start} | "
                            f"Length: {signal.length}",
                            40
                        )
        finally:
            painter.end()

    # =========================================================
    # CURRENT DATABASE
    # =========================================================

    def get_current_database(self):

        if (
            self.current_file
            and
            self.current_file
            in self.databases
        ):

            return self.databases[
                self.current_file
            ]

        return None

    # =========================================================
    # STATISTICS
    # =========================================================

    def update_statistics(self):

        database = (
            self.get_current_database()
        )

        if database is None:

            self.nodes_value.setText(
                "0"
            )

            self.messages_value.setText(
                "0"
            )

            self.signals_value.setText(
                "0"
            )

            return

        self.nodes_value.setText(
            str(
                len(
                    database.nodes
                )
            )
        )

        self.messages_value.setText(
            str(
                len(
                    database.messages
                )
            )
        )

        signal_count = sum(
            len(
                message.signals
            )
            for message
            in database.messages
        )

        self.signals_value.setText(
            str(
                signal_count
            )
        )

    # =========================================================
    # TREE CLICKED
    # =========================================================

    def tree_clicked(
        self,
        item,
        column
    ):

        self.file_action_visible_path = None
        self.file_list.clearSelection()
        for index in range(self.file_list.count()):
            self.set_file_row_selected(self.file_list.item(index), False)

        data = item.data(
            0,
            Qt.UserRole
        )

        if not data:

            return

        if data[0] == "file_root":

            path = data[1]
            if getattr(self, "pending_create_node_path", None) == path:
                self.pending_create_node_path = None
                self.create_node()
            else:
                self.show_overview()

        elif data[0] == "node":

            # Clicking a node opens only its next level (messages).
            # It never collapses other already-open branches.
            item.setExpanded(True)

            self.show_node_details(
                data[1]
            )

        elif data[0] == "message":

            # Clicking a message opens only its next level (signals).
            # It never collapses other already-open branches.
            item.setExpanded(True)

            self.show_message_details(
                data[1]
            )

        elif data[0] == "signal":

            self.show_signal_details(
                data[1],
                data[2]
            )

    # =========================================================
    # DOUBLE CLICK
    # =========================================================

    def tree_double_clicked(self, item, column):
        self.file_action_visible_path = None
        self.file_list.clearSelection()
        for index in range(self.file_list.count()):
            self.set_file_row_selected(self.file_list.item(index), False)
        data = item.data(0, Qt.UserRole)
        if not data:
            return

        if data[0] == "message":
            message = data[1]
            node = None
            parent = item.parent()
            while parent is not None:
                parent_data = parent.data(0, Qt.UserRole)
                if parent_data and parent_data[0] == "node":
                    node = parent_data[1]
                    break
                parent = parent.parent()

            dialog = MessageEditorDialog(
                self,
                message,
                self.get_current_database(),
                node,
                self.refresh_after_edit
            )
            dialog.exec()

        elif data[0] == "signal":
            message, signal = data[1], data[2]
            dialog = SignalEditorDialog(
                self,
                message,
                signal,
                self.refresh_after_edit
            )
            dialog.exec()

    def refresh_after_edit(self):
        force_expand_key = getattr(
            self,
            "_tree_expand_after_refresh",
            None
        )

        self.update_database_tree(
            force_expand_key=force_expand_key
        )

        self._tree_expand_after_refresh = None

        self.update_statistics()


    def update_search_clear_button_style(self):
        if not hasattr(self, "search_clear_button"):
            return

        if self.current_theme == "dark":
            self.search_clear_button.setStyleSheet("""
                QToolButton {
                    background: transparent;
                    color: #FFFFFF;
                    border: none;
                    font-size: 20px;
                    font-weight: 600;
                    padding: 0px;
                }
                QToolButton:hover {
                    background: transparent;
                    color: #FFFFFF;
                }
            """)
        else:
            self.search_clear_button.setStyleSheet("""
                QToolButton {
                    background: transparent;
                    color: #000000;
                    border: none;
                    font-size: 20px;
                    font-weight: 600;
                    padding: 0px;
                }
                QToolButton:hover {
                    background: transparent;
                    color: #000000;
                }
            """)

        self.search_clear_button.move(
            self.search_box.width() - self.search_clear_button.width() - 6,
            (self.search_box.height() - self.search_clear_button.height()) // 2
        )

    def apply_current_theme(self):
        """Apply the selected theme."""
        base_style = LIGHT_STYLE if self.current_theme == "light" else DARK_STYLE
        app.setStyleSheet(base_style)
        self.sidebar_tree.arrow_idle = QColor(
            "#000000" if self.current_theme == "light" else "#FFFFFF"
        )
        self.sidebar_tree.viewport().update()
        self.update_search_clear_button_style()

    def eventFilter(self, watched, event):
        """Handle keyboard shortcuts for the database tree."""
        if event.type() == QEvent.KeyPress and (watched is self.sidebar_tree or watched is self.sidebar_tree.viewport()):
            item = self.sidebar_tree.currentItem()
            if item is not None:
                data = item.data(0, Qt.UserRole)
                if data:
                    modifiers = event.modifiers()
                    key = event.key()

                    if modifiers & Qt.ControlModifier and key == Qt.Key_C:
                        if data[0] == "node":
                            self.copy_node(data[1])
                        elif data[0] == "message":
                            self.copy_message(data[1])
                        elif data[0] == "signal":
                            self.copy_signal(data[1], data[2])
                        return True

                    if modifiers & Qt.ControlModifier and key == Qt.Key_V:
                        if data[0] == "node":
                            self.paste_node(data[1])
                        elif data[0] == "message":
                            self.paste_message(data[1])
                        elif data[0] == "signal":
                            self.paste_signal(data[1])
                        return True

                    if key == Qt.Key_F2 and not modifiers:
                        if data[0] == "node":
                            self.rename_node(data[1])
                        elif data[0] == "message":
                            self.rename_message(data[1])
                        elif data[0] == "signal":
                            self.rename_signal(data[1], data[2])
                        return True

                    if key in (Qt.Key_Delete, Qt.Key_Backspace) and not modifiers:
                        if data[0] == "node":
                            self.delete_node(data[1])
                        elif data[0] == "message":
                            self.delete_message(data[1])
                        elif data[0] == "signal":
                            self.delete_signal(data[1], data[2])
                        return True


        return super().eventFilter(watched, event)

    # =========================================================
    # RIGHT CLICK MENU
    # =========================================================

    def show_tree_context_menu(
        self,
        position
    ):

        item = self.sidebar_tree.itemAt(
            position
        )

        if item is None:

            return

        data = item.data(
            0,
            Qt.UserRole
        )

        if not data:

            return

        # -----------------------------------------------------
        # DBC FILE ROOT
        # -----------------------------------------------------

        if data[0] == "file_root":
            menu = QMenu(self)
            new_node_action = menu.addAction("+  New Node")

            selected_action = menu.exec(
                self.sidebar_tree.viewport().mapToGlobal(position)
            )

            if selected_action == new_node_action:
                self.create_node()

        # -----------------------------------------------------
        # NODE
        # -----------------------------------------------------

        elif data[0] == "node":
            menu = QMenu(self)
            new_message_action = menu.addAction("+  New Message")

            edit_menu = menu.addMenu("Edit")
            copy_action = edit_menu.addAction("Copy")
            copy_action.setShortcut("Ctrl+C")
            paste_action = edit_menu.addAction("Paste")
            paste_action.setShortcut("Ctrl+V")
            rename_action = edit_menu.addAction("Rename")
            rename_action.setShortcut("F2")
            delete_action = edit_menu.addAction("Delete")
            delete_action.setShortcut("Del")

            selected_action = menu.exec(
                self.sidebar_tree.viewport().mapToGlobal(position)
            )

            if selected_action == new_message_action:
                self.create_message_for_node(data[1])
            elif selected_action == copy_action:
                self.copy_node(data[1])
            elif selected_action == paste_action:
                self.paste_node(data[1])
            elif selected_action == rename_action:
                self.rename_node(data[1])
            elif selected_action == delete_action:
                self.delete_node(data[1])

        # -----------------------------------------------------
        # MESSAGE
        # -----------------------------------------------------

        elif data[0] == "message":

            menu = QMenu(
                self
            )

            edit_action = menu.addAction(
                "✎  Open Message Editor"
            )
            new_signal_action = menu.addAction(
                "+  New Signal"
            )

            edit_menu = menu.addMenu("Edit")
            copy_action = edit_menu.addAction("Copy")
            copy_action.setShortcut("Ctrl+C")
            paste_action = edit_menu.addAction("Paste")
            paste_action.setShortcut("Ctrl+V")
            rename_action = edit_menu.addAction("Rename")
            rename_action.setShortcut("F2")
            delete_action = edit_menu.addAction("Delete")
            delete_action.setShortcut("Del")

            selected_action = menu.exec(
                self.sidebar_tree
                .viewport()
                .mapToGlobal(
                    position
                )
            )

            if selected_action == new_signal_action:
                self.create_signal_for_message(
                    data[1]
                )

            elif selected_action == copy_action:
                self.copy_message(data[1])

            elif selected_action == paste_action:
                self.paste_message(data[1])

            elif selected_action == rename_action:
                self.rename_message(data[1])

            elif selected_action == delete_action:
                self.delete_message(data[1])

            elif selected_action == edit_action:

                self._tree_expand_after_refresh = (
                    "message",
                    data[1].frame_id,
                    data[1].name
                )
                node = None
                parent = item.parent()
                while parent is not None:
                    parent_data = parent.data(0, Qt.UserRole)
                    if parent_data and parent_data[0] == "node":
                        node = parent_data[1]
                        break
                    parent = parent.parent()

                dialog = MessageEditorDialog(
                    self,
                    data[1],
                    self.get_current_database(),
                    None,
                    self.refresh_after_edit
                )

                dialog.exec()


                self.update_database_tree()

                self.update_statistics()

                self.show_message_details(
                    data[1]
                )

        # -----------------------------------------------------
        # SIGNAL
        # -----------------------------------------------------

        elif data[0] == "signal":

            menu = QMenu(
                self
            )

            edit_action = menu.addAction(
                "✎  Open Signal Editor"
            )

            edit_menu = menu.addMenu("Edit")
            copy_action = edit_menu.addAction("Copy")
            copy_action.setShortcut("Ctrl+C")
            paste_action = edit_menu.addAction("Paste")
            paste_action.setShortcut("Ctrl+V")
            rename_action = edit_menu.addAction("Rename")
            rename_action.setShortcut("F2")
            delete_action = edit_menu.addAction("Delete")
            delete_action.setShortcut("Del")

            selected_action = menu.exec(
                self.sidebar_tree
                .viewport()
                .mapToGlobal(
                    position
                )
            )

            if selected_action == edit_action:

                self._tree_expand_after_refresh = (
                    "message",
                    data[1].frame_id,
                    data[1].name
                )

                dialog = SignalEditorDialog(
                    self,
                    data[1],
                    data[2],
                    self.refresh_after_edit
                )

                dialog.exec()


                self.update_database_tree()

                self.update_statistics()

                self.show_signal_details(
                    data[1],
                    data[2]
                )

            elif selected_action == copy_action:

                self.copy_signal(
                    data[1],
                    data[2]
                )

            elif selected_action == paste_action:

                self.paste_signal(
                    data[1]
                )

            elif selected_action == rename_action:

                self.rename_signal(
                    data[1],
                    data[2]
                )

            elif selected_action == delete_action:

                self.delete_signal(
                    data[1],
                    data[2]
                )

        # -----------------------------------------------------
        # NODE
        #
        # Nothing happens.
        # -----------------------------------------------------

        # -----------------------------------------------------
        # FILE ROOT
        #
        # Nothing happens.
        # -----------------------------------------------------

        # -----------------------------------------------------
        # SIGNALS HEADER
        #
        # Nothing happens.
        # -----------------------------------------------------

