    # =========================================================
    # SIGNAL DETAILS
    # =========================================================

    def show_signal_details(
        self,
        message,
        signal
    ):

        self.clear_main_layout()

        self.page_title.setText(
            signal.name
        )

        self.page_subtitle.setText(
            f"Signal • {message.name}"
        )

        self.add_detail(
            "Signal Name",
            signal.name
        )

        self.add_detail(
            "Message",
            message.name
        )

        self.add_detail(
            "Start Bit",
            signal.start
        )

        self.add_detail(
            "Length",
            f"{signal.length} bits"
        )

        self.add_detail(
            "Byte Order",
            signal.byte_order
        )

        self.add_detail(
            "Signed",
            "Yes"
            if signal.is_signed
            else
            "No"
        )

        self.add_detail(
            "Factor",
            signal.scale
        )

        self.add_detail(
            "Offset",
            signal.offset
        )

        self.add_detail(
            "Minimum",
            signal.minimum
            if signal.minimum is not None
            else
            "Not specified"
        )

        self.add_detail(
            "Maximum",
            signal.maximum
            if signal.maximum is not None
            else
            "Not specified"
        )

        self.add_detail(
            "Unit",
            signal.unit
            if signal.unit
            else
            "Not specified"
        )
        # Value table summary
        choices = getattr(signal, "choices", None)
        if choices:
            summary_parts = [
                f"{value} = {desc}"
                for value, desc in sorted(choices.items(), key=lambda x: x[0])
            ]
            if len(summary_parts) > 8:
                shown = ", ".join(summary_parts[:8]) + f"  … (+{len(summary_parts) - 8} more)"
            else:
                shown = ", ".join(summary_parts)
            self.add_detail("Value Table", shown)
        else:
            self.add_detail("Value Table", "None")

        self.main_layout.addStretch()

