    # =========================================================
    # SEARCH
    # =========================================================

    def update_search_completer(self):

        if not hasattr(self, "search_completer_model"):
            return

        database = (
            self.get_current_database()
        )

        if database is None:
            self.search_completer_model.setStringList([])
            return

        suggestions = []

        # -----------------------------------------------------
        # NODE NAMES
        # -----------------------------------------------------

        for node in database.nodes:
            if node.name:
                suggestions.append(node.name)

        # -----------------------------------------------------
        # MESSAGE NAMES AND IDS
        # -----------------------------------------------------

        for message in database.messages:
            if message.name:
                suggestions.append(message.name)

            suggestions.append(
                f"0x{message.frame_id:X}"
            )

            # -------------------------------------------------
            # SIGNAL NAMES
            # -------------------------------------------------

            for signal in message.signals:
                if signal.name:
                    suggestions.append(signal.name)

        # Remove duplicates while preserving database order.
        suggestions = list(
            dict.fromkeys(suggestions)
        )

        self.search_completer_model.setStringList(
            suggestions
        )

    def select_search_completion(self, text):

        self.search_box.setText(text)
        self.search_box.setFocus()
        self.search_box.setCursorPosition(
            len(text)
        )

    def search_database(
        self,
        text
    ):

        if not text.strip():

            if self.current_file:

                self.update_database_tree()

            return

        database = (
            self.get_current_database()
        )

        if database is None:

            return

        text = (
            text.lower()
            .strip()
        )

        self.sidebar_tree.clear()

        root = QTreeWidgetItem(
            self.sidebar_tree
        )

        root.setText(
            0,
            "⌕ SEARCH RESULTS"
        )

        root.setExpanded(
            True
        )

        found = 0

        # -----------------------------------------------------
        # NODE SEARCH
        # -----------------------------------------------------

        for node in database.nodes:

            if text in node.name.lower():

                item = QTreeWidgetItem(
                    root
                )

                item.setText(
                    0,
                 node.name
                )
                item.setIcon(0, self.node_tree_icon)

                item.setData(
                    0,
                    Qt.UserRole,
                    (
                        "node",
                        node
                    )
                )

                found += 1

        # -----------------------------------------------------
        # MESSAGE SEARCH
        # -----------------------------------------------------

        for message in database.messages:

            if(
                text in message.name.lower()
                or
                (
                    text.startswith("0x")
                    and
                    text in f"0x{message.frame_id:X}".lower()
                )
            ):

                item = QTreeWidgetItem(
                    root
                )

                item.setText(
                    0,
                    message.name
                )
                item.setIcon(0, self.message_tree_icon)

                item.setData(
                    0,
                    Qt.UserRole,
                    (
                        "message",
                        message
                    )
                )

                found += 1

            # -------------------------------------------------
            # SIGNAL SEARCH
            # -------------------------------------------------

            for signal in message.signals:

                if text in signal.name.lower():

                    item = QTreeWidgetItem(
                        root
                    )

                    item.setText(
                        0,
                        signal.name
                    )
                    item.setIcon(0, self.signal_tree_icon)

                    item.setData(
                        0,
                        Qt.UserRole,
                        (
                           "signal",
                            message,
                            signal
                        )
                    )

                    found += 1

        root.setText(
            0,
            f"⌕ SEARCH RESULTS ({found})"
        )

        if found == 0:

            QTreeWidgetItem(
                root,
                [
                    "No results found"
                ]
            )
