    # =========================================================
    # THEME
    # =========================================================

    def change_theme(self, theme_name):

        theme = "light" if theme_name == "Light" else "dark"
        self.current_theme = theme
        self.settings.setValue("theme", theme)
        self.apply_current_theme()
        self.update_tree_icons()
        self.update_header_icons()

    def toggle_theme(self):
        self.change_theme("Light" if self.current_theme == "dark" else "Dark")

    def update_tree_icons(self):
        # Light: black when not selected, white when selected. Dark: always white.
        if self.current_theme == "light":
            idle = "#000000"
            selected = "#FFFFFF"
        else:
            idle = "#FFFFFF"
            selected = "#FFFFFF"

        self.node_tree_icon = create_tinted_embedded_icon(NODE_TREE_ICON_DATA, idle)
        self.node_tree_icon_selected = create_tinted_embedded_icon(NODE_TREE_ICON_DATA, selected)
        self.message_tree_icon = create_tinted_embedded_icon(MESSAGE_TREE_ICON_DATA, idle)
        self.message_tree_icon_selected = create_tinted_embedded_icon(MESSAGE_TREE_ICON_DATA, selected)
        self.file_tree_icon = create_tinted_embedded_icon(FILE_TREE_ICON_DATA, idle)
        self.file_tree_icon_selected = create_tinted_embedded_icon(FILE_TREE_ICON_DATA, selected)
        self.signal_tree_icon = create_tinted_embedded_icon(SIGNAL_TREE_ICON_DATA, idle)
        self.signal_tree_icon_selected = create_tinted_embedded_icon(SIGNAL_TREE_ICON_DATA, selected)

        self.refresh_tree_item_icons()

    def refresh_tree_item_icons(self):
        """Apply black/white tree icons based on selection (light theme only cares)."""
        def icon_for(item):
            data = item.data(0, Qt.UserRole)
            is_sel = item.isSelected()
            if not isinstance(data, tuple):
                return None
            kind = data[0]
            if kind == "file_root":
                return self.file_tree_icon_selected if is_sel else self.file_tree_icon
            if kind == "node":
                return self.node_tree_icon_selected if is_sel else self.node_tree_icon
            if kind == "message":
                return self.message_tree_icon_selected if is_sel else self.message_tree_icon
            if kind == "signal":
                return self.signal_tree_icon_selected if is_sel else self.signal_tree_icon
            return None

        def update_item_icons(item):
            icon = icon_for(item)
            if icon is not None:
                item.setIcon(0, icon)
            for child_index in range(item.childCount()):
                update_item_icons(item.child(child_index))

        if not hasattr(self, "sidebar_tree"):
            return
        for top_index in range(self.sidebar_tree.topLevelItemCount()):
            update_item_icons(self.sidebar_tree.topLevelItem(top_index))

    def update_header_icons(self):
        if not hasattr(self, "theme_button"):
            return

        icon_color = "#253140" if self.current_theme == "light" else "#FFFFFF"

        if self.current_theme == "light":
            self.theme_button.setIcon(self.light_theme_icon)
        else:
            self.theme_button.setIcon(
                self.create_header_icon("sun", icon_color)
            )
        self.theme_button.setIconSize(QSize(22, 22))

    def create_header_icon(self, icon_type, color):
        pixmap = QPixmap(24, 24)
        pixmap.fill(Qt.transparent)

        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing)

        pen = painter.pen()
        pen.setColor(color)
        pen.setWidth(2)
        pen.setCapStyle(Qt.RoundCap)
        pen.setJoinStyle(Qt.RoundJoin)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)

        if icon_type == "home":
            points = [
                QPoint(4, 11),
                QPoint(12, 4),
                QPoint(20, 11)
            ]
            painter.drawPolyline(points)
            painter.drawLine(6, 10, 6, 20)
            painter.drawLine(18, 10, 18, 20)
            painter.drawLine(6, 20, 18, 20)
            painter.drawLine(9, 20, 9, 14)
            painter.drawLine(9, 14, 15, 14)
            painter.drawLine(15, 14, 15, 20)

        elif icon_type == "sun":
            painter.drawEllipse(8, 8, 8, 8)
            painter.drawLine(12, 2, 12, 5)
            painter.drawLine(12, 19, 12, 22)
            painter.drawLine(2, 12, 5, 12)
            painter.drawLine(19, 12, 22, 12)
            painter.drawLine(5, 5, 7, 7)
            painter.drawLine(17, 17, 19, 19)
            painter.drawLine(19, 5, 17, 7)
            painter.drawLine(7, 17, 5, 19)

        elif icon_type == "moon":
            painter.setBrush(Qt.NoBrush)
            painter.drawArc(5, 3, 16, 18, 45 * 16, 250 * 16)

        elif icon_type == "contrast":
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(4, 4, 16, 16)
            painter.drawLine(12, 4, 12, 20)
            painter.drawArc(4, 4, 16, 16, 90 * 16, 180 * 16)

        painter.end()
        return QIcon(pixmap)

    # =========================================================
    # CLEAR MAIN LAYOUT
    # =========================================================

    def clear_main_layout(self):

        while self.main_layout.count():

            item = (
                self.main_layout.takeAt(
                    0
                )
            )

            widget = item.widget()

            if widget:

                widget.deleteLater()

            elif item.layout():

                self.clear_layout(
                    item.layout()
                )

    # =========================================================
    # CLEAR LAYOUT
    # =========================================================

    def clear_layout(
        self,
        layout
    ):

        while layout.count():

            item = (
                layout.takeAt(
                    0
                )
            )

            widget = item.widget()

            if widget:

                widget.deleteLater()

            elif item.layout():

                self.clear_layout(
                    item.layout()
                )


